import React, { useState } from "react";

export default function LiveDemoPage() {
  const [detection, setDetection] = useState({
    rgb: true,
    thermal: false,
    depth: true,
    map: false,
  });

  const getFeedClasses = (active, color) => {
    return `aspect-video bg-black border-4 rounded-xl flex items-center justify-center shadow-xl transition-all duration-300 ${
      active
        ? `border-${color}-400 text-${color}-300 shadow-${color}-500/40 animate-pulse`
        : "border-gray-700 text-gray-500"
    }`;
  };

  const toggleDetection = (key) => {
    setDetection((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="min-h-screen bg-black text-white font-sans p-6">
      <h1 className="text-3xl font-bold text-cyan-400 mb-4 text-center">ADI Drone – Live Demo</h1>

      {/* Camera Feeds Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-4 mb-10">
        <div
          onClick={() => toggleDetection("rgb")}
          className={`${getFeedClasses(detection.rgb, "cyan")} cursor-pointer`}
        >
          RGB Feed (People Detection)
        </div>
        <div
          onClick={() => toggleDetection("thermal")}
          className={`${getFeedClasses(detection.thermal, "orange")} cursor-pointer`}
        >
          Thermal View (Heat Signature)
        </div>
        <div
          onClick={() => toggleDetection("depth")}
          className={`${getFeedClasses(detection.depth, "blue")} cursor-pointer`}
        >
          Depth Map View
        </div>
        <div
          onClick={() => toggleDetection("map")}
          className={`${getFeedClasses(detection.map, "green")} cursor-pointer`}
        >
          Map View (GPS Tracking)
        </div>
      </div>

      {/* Alerts Panel */}
      <div className="bg-gray-800 p-4 rounded-xl shadow-lg max-w-4xl mx-auto">
        <h2 className="text-xl text-cyan-300 mb-3">Live Detection Logs</h2>
        <ul className="space-y-2 text-sm text-gray-300">
          <li>🔥 Fire detected near Zone 3 at 12:05 PM</li>
          <li>🧍‍♂️ 6 people detected in Zone 1</li>
          <li>🤕 Injured person detected – fall posture confirmed</li>
          <li>📍 Drone heading: North-East | Location: 22.5726° N, 88.3639° E</li>
          <li>🎤 Screaming detected – potential panic situation</li>
        </ul>
      </div>
    </div>
  );
}
